-- 08_insertion_periode_5.sql - Portrait de l'Âme (Périodes 5A et 5B)
-- ═══════════════════════════════════════════════════════════════════════════

INSERT INTO cycle_vie_soul_periods (
    period_number, polarity, date_start, date_end, period_name, period_title,
    description_general, traits_positifs, traits_vigilance, professions_favorables,
    sante_vigilance, pays_affinites, conseils, message_cosmique, is_active
) VALUES 
-- PÉRIODE 5A
(5, 'A', '07-23', '08-21', 'Les Guerriers', 'L''Âme Guerrière Passionnée',
E'Vous faites partie de ceux qui atteignent généralement un grand succès et une grande renommée dans leur domaine particulier, bien que ce succès ne soit pas toujours mesuré en termes matériels ou financiers.\n\nVotre âme a appris au cours des incarnations passées une leçon fondamentale : c''est en donnant et en faisant pour les autres que l''on réussit dans la vie.\n\nVous êtes très agressif(ve) dans vos affaires car une nature remplie de détermination et d''énergie vous caractérise. Vous sentez que vous devez vous battre tout au long de votre vie pour éviter de glisser dans une position médiocre.',
E'**La Détermination Inébranlable**\nQuand vous vous engagez dans une cause, rien ne peut vous arrêter.\n\n**L''Énergie Débordante**\nVous possédez des réserves d''énergie que d''autres envient.\n\n**La Générosité du Cœur**\nMalgré votre nature combative, vous donnez librement de vous-même.\n\n**La Capacité d''Accomplir l''Impossible**\nVous excellez dans les tâches que tous les autres ont abandonnées.',
E'**La Tendance aux Accidents**\nVotre agressivité et votre précipitation peuvent vous conduire à des accidents.\n\n**Le Sacrifice Excessif de Soi**\nVotre générosité peut aller jusqu''à négliger vos propres besoins.\n\n**L''Épuisement par la Bataille**\nVotre nature combative peut vous consumer si vous ne savez pas choisir vos batailles.',
E'**Les Métiers du Combat**\n• Avocat plaidant ou défenseur des droits\n• Militant(e) associatif ou politique\n• Journaliste d''investigation\n• Procureur ou magistrat\n\n**Les Métiers de la Transformation**\n• Entrepreneur(se) social(e)\n• Directeur(trice) d''ONG\n• Réformateur(trice) dans tout domaine\n• Coach ou entraîneur sportif',
E'• Inflammations diverses dues au surmenage ou aux rhumes\n• Conditions sanguines liées à l''alimentation excessive\n• Maladies de peau et rhumatismes\n• Angine et risque d''apoplexie\n• Fièvres et états inflammatoires',
E'Votre âme résonne particulièrement avec :\n• Babylone et la Perse antiques\n• L''Égypte et la Palestine\n• Les contrées mystérieuses de l''Orient\n• La Chine et le Japon',
E'1. **Choisissez Vos Batailles** — Toute injustice ne requiert pas votre intervention.\n2. **Prenez Soin de Vous** — Vous ne pouvez aider les autres si vous vous épuisez.\n3. **Célébrez Vos Victoires** — Ne passez pas immédiatement à la bataille suivante.\n4. **Acceptez de l''Aide** — Même les guerriers ont besoin d''alliés.',
E'Vous êtes venu(e) dans cette vie pour combattre les injustices et transformer le monde. Votre énergie et votre détermination sont des dons précieux pour l''humanité. Mais n''oubliez jamais que la plus grande bataille se livre à l''intérieur de soi, et que la victoire suprême est la paix intérieure.',
true),

-- PÉRIODE 5B
(5, 'B', '07-23', '08-21', 'Les Généreux', 'L''Âme Généreuse et Juste',
E'Vous êtes particulièrement enclin(e) à atteindre des positions influentes où vous pouvez affecter le cours des événements et faire le bien à grande échelle.\n\nVos incarnations passées vous ont enseigné que la vraie richesse réside dans ce que l''on donne, pas dans ce que l''on accumule.\n\nBien que vous fassiez partie du même groupe cosmique que ceux qui sont agressifs et combatifs, votre nature est plus contenue. Vous avez la capacité unique de bénéficier aux autres par vos positions.',
E'**L''Influence Positive**\nVous avez le don d''affecter positivement les événements autour de vous.\n\n**La Sagesse Conservatrice**\nVous savez quand agir et quand attendre.\n\n**La Générosité Stratégique**\nVous donnez intelligemment, de manière à maximiser l''impact.\n\n**Le Leadership Éthique**\nLes autres vous suivent parce qu''ils ont confiance en votre intégrité.',
E'**La Tentation du Compromis Excessif**\nVotre désir d''harmonie peut parfois vous conduire à des compromis qui trahissent vos principes.\n\n**L''Impatience Face à la Lenteur du Changement**\nVous savez que les réformes prennent du temps, mais cela peut vous frustrer.\n\n**Le Poids de la Responsabilité**\nLes positions d''influence viennent avec des responsabilités lourdes.',
E'**Les Métiers de l''Influence**\n• Élu(e) local(e) ou régional(e)\n• Directeur(trice) d''entreprise éthique\n• Administrateur(trice) d''institution publique\n• Conseiller(ère) politique ou stratégique\n\n**Les Métiers du Service**\n• Directeur(trice) d''association caritative\n• Gestionnaire de fonds philanthropiques\n• Consultant(e) en responsabilité sociale\n• Médiateur(trice) communautaire',
E'• Inflammations et conditions sanguines\n• Maladies de peau et rhumatismes\n• Risques cardiovasculaires\n• Fièvres et états inflammatoires',
E'Comme vos proches cosmiques :\n• La Perse et l''Égypte anciennes\n• La Palestine et la Chine\n• Le Japon et les terres d''Orient',
E'1. **Restez Fidèle à Vos Principes** — Même quand le compromis semble plus facile.\n2. **Célébrez les Petites Victoires** — Le changement s''accumule progressivement.\n3. **Entourez-Vous de Personnes Intègres** — Votre équipe reflète vos valeurs.\n4. **Prenez Soin de Votre Santé** — Vous ne pouvez servir les autres si vous êtes épuisé(e).',
E'Vous êtes venu(e) dans cette vie pour construire un monde plus juste, un pas à la fois. Votre mission n''est pas de tout changer du jour au lendemain, mais de créer des fondations durables pour une société meilleure. Votre patience et votre persévérance sont vos plus grands atouts.',
true);

SELECT '✅ PÉRIODE 5 (5A + 5B) INSÉRÉE' as status;
